// Build the prompt.
//
// This node is the reason answer generation lives in n8n: the wording below can be
// edited on the canvas without redeploying the app.
//
// The excerpts arrive already read out of Postgres under the student's own session, so
// RLS has already decided what is allowed in here. This node must not fetch anything
// else - it only formats what it was given.
//
// Excerpt numbering must stay in the order received. The app maps the [n] citations in
// the answer back to chunk ids by position, so reordering here would misattribute
// sources.

const body = $input.first().json.body ?? $input.first().json;
const { question, chunks } = body;

if (typeof question !== 'string' || !question.trim()) {
  throw new Error('payload must include a non-empty question');
}
if (!Array.isArray(chunks) || chunks.length === 0) {
  throw new Error('payload must include at least one chunk');
}

const RULES = `You are a defense coach for a final-year university student. You are helping them understand and defend their own project.

You will be given numbered excerpts from the student's project, followed by their question.

Rules:
- Answer only from the excerpts. They are the student's own work and are the sole source of truth.
- If the excerpts do not contain the answer, say so plainly and name what is missing. Never fill a gap with general knowledge - the student would carry that into their defense believing it was in their project.
- Cite the excerpts you used by their number, like [1] or [2][4], placed where the claim is made.
- Write the way a supervisor would speak: direct, specific, and in the student's own terminology rather than generic academic phrasing.
- Be concise. Answer what was asked, then stop.`;

const excerpts = chunks
  .map((c, i) => {
    const where = c.chapter
      ? `Chapter ${c.chapter}${c.label ? ` - ${c.label}` : ''}`
      : (c.label || 'Unlabelled section');
    return `[${i + 1}] (${where})\n${c.content}`;
  })
  .join('\n\n---\n\n');

const prompt = `${RULES}\n\nExcerpts from the project:\n\n${excerpts}\n\n---\n\nStudent's question: ${question.trim()}`;

return [{ json: { prompt } }];

// Normalise whatever the chain returned into a single answer string.
//
// chainLlm puts the completion under `text`, but the key has moved between versions, so
// the fallbacks below keep this working across an n8n upgrade rather than failing with an
// empty answer the student cannot act on.

const j = $input.first().json ?? {};
const answer = j.text ?? j.response ?? j.output ?? j.data ?? '';

if (typeof answer !== 'string' || !answer.trim()) {
  throw new Error('the model returned an empty answer');
}

return [{ json: { answer: answer.trim() } }];
